export type RegistryLoadError = NonNullable<
  McpListResponse["load_errors"]
>[number];

/** Typed registry-mutation failure the UI can render with guidance. */
export type RegistryFailure = {
  code:
    | "duplicate_name"
    | "invalid_name"
    | "invalid_manifest"
    | "mcp_limit"
    | "skill_limit"
    | "io_error"
    | "not_found"
    | "daemon";
  message: string;
};

export type McpMutationOutcome =
  { ok: true; server?: McpServer } | (RegistryFailure & { ok: false });
export type SkillMutationOutcome =
  { ok: true; detail?: SkillDetail } | (RegistryFailure & { ok: false });

async function mutateRegistry<T>(
  method: "POST" | "PATCH" | "DELETE",
  path: string,
  body?: unknown,
): Promise<{ ok: true; value?: T } | (RegistryFailure & { ok: false })> {
  let res: Response;
  try {
    res = await fetch(`${BASE}${path}`, {
      method,
      headers:
        body === undefined
          ? { Accept: "application/json" }
          : { Accept: "application/json", "Content-Type": "application/json" },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch (err) {
    return {
      ok: false,
      code: "daemon",
      message: `daemon unreachable (${String(err)})`,
    };
  }
  if (res.status === 204) return { ok: true };
  if (res.ok) return { ok: true, value: (await res.json()) as T };
  const errBody = (await res.json().catch(() => null)) as {
    code?: string;
    message?: string;
  } | null;
  const code = errBody?.code as RegistryFailure["code"] | undefined;
  return {
    ok: false,
    code: code ?? "daemon",
    message: errBody?.message ?? `daemon answered ${res.status}`,
  };
}

