type McpImportResponse =
  operations["importMcps"]["responses"][200]["content"]["application/json"];
export type McpImportRequest =
  operations["importMcps"]["requestBody"]["content"]["application/json"];
export type McpImportOutcome = McpImportResponse["results"][number];
export type McpImportResult = McpImportResponse;
export type McpImportFailureReason =
  "invalid_import" | "not_found" | "invalid_manifest" | "io_error" | "daemon";

/** Import outcome: per-entry results are data; only document-level
 * rejections and transport failures are errors. */
export type McpImportCallResult =
  | { ok: true; result: McpImportResult }
  | { ok: false; code: McpImportFailureReason; message: string };

export async function importMcps(
  req: McpImportRequest,
): Promise<McpImportCallResult> {
  let res: Response;
  try {
    res = await fetch(`${BASE}${MCP_IMPORT}`, {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(req),
    });
  } catch (err) {
    return {
      ok: false,
      code: "daemon",
      message: `daemon unreachable (${String(err)})`,
    };
  }
  if (res.ok)
    return { ok: true, result: (await res.json()) as McpImportResponse };
  const errBody = (await res.json().catch(() => null)) as {
    code?: string;
    message?: string;
  } | null;
  const code = (errBody?.code ?? "daemon") as McpImportFailureReason;
  return {
    ok: false,
    code,
    message: errBody?.message ?? `daemon answered ${res.status}`,
  };
}

/** Probe result: every per-transport outcome is data; only transport /
 * unknown-server failures are errors (probe failures are 200 bodies). */
export type McpTestOutcome =
  { ok: true; result: McpTestResult } | (RegistryFailure & { ok: false });

