const MARKET_ROUTES = {
  search: "/api/skills/marketplace/search" as const satisfies keyof paths,
  preview: "/api/skills/marketplace/preview" as const satisfies keyof paths,
  install: "/api/skills/marketplace/install" as const satisfies keyof paths,
  importPreview: "/api/skills/import/preview" as const satisfies keyof paths,
  importCommit: "/api/skills/import/commit" as const satisfies keyof paths,
};

export type MarketFailure = { ok: false; code: string; message: string };
export type MarketSearchOutcome =
  { ok: true; skills: MarketSkill[] } | MarketFailure;

/** Daemon-proxied skills.sh search (typed index-unreachable failure). */
export async function searchMarketplace(
  query: string,
): Promise<MarketSearchOutcome> {
  let res: Response;
  try {
    res = await fetch(
      `${BASE}${MARKET_ROUTES.search}?q=${encodeURIComponent(query)}`,
      { headers: { Accept: "application/json" } },
    );
  } catch (err) {
    return {
      ok: false,
      code: "daemon",
      message: `daemon unreachable (${String(err)})`,
    };
  }
  if (res.ok)
    return {
      ok: true,
      skills: ((await res.json()) as MarketSearchResponse).skills ?? [],
    };
  const errBody = (await res.json().catch(() => null)) as {
    message?: string;
  } | null;
  return {
    ok: false,
    code: res.status === 502 ? "index_unreachable" : "daemon",
    message: errBody?.message ?? `daemon answered ${res.status}`,
  };
}

async function marketPost<T>(
  path: string,
  body: unknown,
): Promise<{ ok: true; value: T } | MarketFailure> {
  let res: Response;
  try {
    res = await fetch(`${BASE}${path}`, {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    });
  } catch (err) {
    return {
      ok: false,
      code: "daemon",
      message: `daemon unreachable (${String(err)})`,
    };
  }
  if (res.ok) return { ok: true, value: (await res.json()) as T };
  const errBody = (await res.json().catch(() => null)) as {
    code?: string;
    message?: string;
  } | null;
  return {
    ok: false,
    code: errBody?.code ?? `status_${res.status}`,
    message: errBody?.message ?? `daemon answered ${res.status}`,
  };
}

