/** Continue: grant additional iterations to a live research run. */
export async function continueSession(
  sessionId: string,
  additionalIterations: number,
): Promise<{ ok: true; granted: number } | { ok: false; error: string }> {
  try {
    const res = await fetch(
      `${BASE}/api/sessions/${encodeURIComponent(sessionId)}/continue`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ additional_iterations: additionalIterations }),
      },
    );
    if (res.ok) {
      const body = (await res.json()) as { granted: number };
      return { ok: true, granted: body.granted };
    }
    const body = (await res.json().catch(() => null)) as {
      message?: string;
    } | null;
    return {
      ok: false,
      error: body?.message ?? `daemon answered ${res.status}`,
    };
  } catch {
    return { ok: false, error: "daemon unreachable" };
  }
}
